// ── Lift log ────────────────────────────────────────────────────────
// Estimated 1RM using the Epley formula. Treats weight 0 / bodyweight as no e1RM.
const epley1RM = (weight, reps) => {
  if (!weight || weight <= 0 || !reps || reps <= 0) return null;
  if (reps === 1) return weight;
  return Math.round(weight * (1 + reps / 30) * 10) / 10;
};

// Best e1RM across a session (highest of each set's e1RM)
const sessionBest1RM = (sets) => {
  if (!sets || sets.length === 0) return null;
  const ones = sets.map(s => epley1RM(s.weight, s.reps)).filter(v => v !== null);
  return ones.length ? Math.max(...ones) : null;
};

// Total volume for a session (sum of weight × reps)
const sessionVolume = (sets) => {
  if (!sets || sets.length === 0) return 0;
  return sets.reduce((sum, s) => sum + ((s.weight || 0) * (s.reps || 0)), 0);
};

// Top set (heaviest weight) in a session
const topSet = (sets) => {
  if (!sets || sets.length === 0) return null;
  const withWeight = sets.filter(s => s.weight && s.weight > 0);
  if (withWeight.length === 0) return null;
  return withWeight.reduce((a, b) => (a.weight >= b.weight ? a : b));
};

