// Build a series of weight readings trending from `start` to `end` over `days` days
// with daily fluctuations. Skips a few days here and there for realism.
function buildWeightSeries(start, end, days, skipChance = 0.15, seed = 1) {
  let s = seed;
  const rnd = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  const series = [];
  for (let i = days - 1; i >= 0; i--) {
    if (rnd() < skipChance && i !== 0) continue; // some days unlogged
    const t = (days - 1 - i) / Math.max(days - 1, 1);
    const trend = start + (end - start) * t;
    const noise = (rnd() - 0.5) * 0.8;     // ±0.4 kg daily fluctuation
    series.push({ date: dateOffset(-i), kg: Math.round((trend + noise) * 10) / 10 });
  }
  return series;
}

function buildMoodSeries(avg, days, seed = 1) {
  let s = seed;
  const rnd = () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  const out = [];
  for (let i = days - 1; i >= 0; i--) {
    if (rnd() < 0.2 && i !== 0) continue;
    const score  = Math.max(1, Math.min(10, Math.round(avg + (rnd() - 0.5) * 4)));
    const energy = Math.max(1, Math.min(10, Math.round(avg + (rnd() - 0.5) * 4)));
    const sleep  = Math.max(1, Math.min(10, Math.round(avg + 0.5 + (rnd() - 0.5) * 3)));
    out.push({ date: dateOffset(-i), score, energy, sleep });
  }
  return out;
}

