// ── Macro ring (compact SVG) ─────────────────────────────────────────
function MacroRing({ value, goal, color, label, sub, size = 88 }) {
  const pct = Math.min(value / Math.max(goal, 1), 1);
  const r = (size - 10) / 2;
  const c = 2 * Math.PI * r;
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
      <div style={{ position: "relative", width: size, height: size }}>
        <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
          <circle cx={size/2} cy={size/2} r={r} stroke={`${T.border}`} strokeWidth="6" fill="none" />
          <circle cx={size/2} cy={size/2} r={r} stroke={color} strokeWidth="6" fill="none"
            strokeDasharray={c} strokeDashoffset={c - pct * c} strokeLinecap="round"
            style={{ transition: "stroke-dashoffset 0.5s ease" }} />
        </svg>
        <div style={{
          position: "absolute", inset: 0, display: "flex",
          flexDirection: "column", alignItems: "center", justifyContent: "center",
        }}>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 18, color: T.text, letterSpacing: 1 }}>{value}</div>
          <div style={{ fontFamily: FONT_MONO, fontSize: 9, color: T.muted }}>/ {goal}</div>
        </div>
      </div>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontFamily: FONT_MONO, fontSize: 9, letterSpacing: 1.5, color: T.muted, textTransform: "uppercase" }}>{label}</div>
        {sub && <div style={{ fontFamily: FONT_BODY, fontSize: 10, color, marginTop: 2 }}>{sub}</div>}
      </div>
    </div>
  );
}

