// ── Line chart (responsive SVG) ──────────────────────────────────────
function LineChart({ data, color = T.pacific, height = 140, valueKey = "value",
                    yMin: yMinProp, yMax: yMaxProp, formatY, unit, fixed = 1 }) {
  if (!data || data.length === 0) {
    return (
      <div style={{
        height, display: "flex", alignItems: "center", justifyContent: "center",
        background: T.surface, border: `1px dashed ${T.border}`, borderRadius: 10,
        color: T.muted, fontSize: 12,
      }}>
        Not enough data yet — log a few entries to see your trend.
      </div>
    );
  }

  // Fixed coordinate system, scaled via viewBox for responsiveness
  const W = 600, H = 200;
  const pad = { top: 14, right: 14, bottom: 26, left: 36 };
  const cw = W - pad.left - pad.right;
  const ch = H - pad.top - pad.bottom;

  const ys = data.map(d => d[valueKey]);
  const dataMin = Math.min(...ys);
  const dataMax = Math.max(...ys);
  // Add a little headroom so the line never touches edges
  const headroom = (dataMax - dataMin) * 0.15 || 1;
  const yMin = yMinProp ?? (dataMin - headroom);
  const yMax = yMaxProp ?? (dataMax + headroom);
  const range = (yMax - yMin) || 1;

  const px = (i) => pad.left + (data.length === 1 ? cw / 2 : (i / (data.length - 1)) * cw);
  const py = (v) => pad.top + (1 - (v - yMin) / range) * ch;

  const points = data.map((d, i) => [px(i), py(d[valueKey])]);
  const linePath = points.map((p, i) => (i === 0 ? "M" : "L") + ` ${p[0]} ${p[1]}`).join(" ");
  const areaPath = `${linePath} L ${points[points.length - 1][0]} ${pad.top + ch} L ${points[0][0]} ${pad.top + ch} Z`;

  // Y-axis tick marks
  const ticks = 4;
  const tickValues = Array.from({ length: ticks }, (_, i) => yMin + (range * i) / (ticks - 1));

  // X-axis labels: first, middle, last
  const xLabels = data.length <= 2 ? data : [
    { d: data[0], idx: 0 },
    { d: data[Math.floor(data.length / 2)], idx: Math.floor(data.length / 2) },
    { d: data[data.length - 1], idx: data.length - 1 },
  ].map(o => o.d ? { ...o.d, _idx: o.idx } : null).filter(Boolean);

  const fmtDate = (iso) => {
    const d = new Date(iso);
    return d.toLocaleDateString("en-GB", { day: "numeric", month: "short" });
  };
  const fmtY = formatY || ((v) => `${Number(v).toFixed(fixed)}${unit ? unit : ""}`);

  const last = points[points.length - 1];
  const lastVal = data[data.length - 1][valueKey];
  const gradId = `grad-${color.replace("#", "")}-${data.length}`;

  return (
    <div style={{ width: "100%", overflow: "hidden" }}>
      <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none"
           width="100%" height={height}
           style={{ display: "block" }}>
        <defs>
          <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"   stopColor={color} stopOpacity="0.22" />
            <stop offset="100%" stopColor={color} stopOpacity="0" />
          </linearGradient>
        </defs>

        {/* Y-axis grid + labels */}
        {tickValues.map((v, i) => {
          const yy = py(v);
          return (
            <g key={i}>
              <line x1={pad.left} x2={W - pad.right} y1={yy} y2={yy}
                    stroke={T.border} strokeWidth="1" strokeDasharray="2 4" opacity="0.7" />
              <text x={pad.left - 6} y={yy + 4} textAnchor="end"
                    fontFamily={FONT_MONO} fontSize="10" fill={T.muted}>
                {fmtY(v)}
              </text>
            </g>
          );
        })}

        {/* X-axis labels */}
        {xLabels.map((d, i) => (
          <text key={i} x={px(d._idx)} y={H - 6} textAnchor="middle"
                fontFamily={FONT_MONO} fontSize="10" fill={T.muted}>
            {fmtDate(d.date)}
          </text>
        ))}

        {/* Area fill + line */}
        {data.length > 1 && <path d={areaPath} fill={`url(#${gradId})`} />}
        <path d={linePath} fill="none" stroke={color} strokeWidth="2.4"
              strokeLinejoin="round" strokeLinecap="round" />

        {/* Last point highlighted */}
        <circle cx={last[0]} cy={last[1]} r="6" fill={T.bgDeep} stroke={color} strokeWidth="2.4" />
        <circle cx={last[0]} cy={last[1]} r="2.5" fill={color} />

        {/* Last value badge */}
        <g transform={`translate(${Math.min(last[0] + 10, W - 70)}, ${Math.max(last[1] - 18, pad.top + 4)})`}>
          <rect x="0" y="0" width="64" height="22" rx="11" fill={color} />
          <text x="32" y="15" textAnchor="middle"
                fontFamily={FONT_DISPLAY} fontSize="13" fill="#ffffff" letterSpacing="1">
            {fmtY(lastVal)}
          </text>
        </g>
      </svg>
    </div>
  );
}

// ── Sparkline (compact inline chart) ─────────────────────────────────
function Sparkline({ data, color, height = 36, valueKey = "value" }) {
  if (!data || data.length < 2) {
    return <div style={{ height, color: T.muted, fontSize: 10, fontFamily: FONT_MONO,
      display: "flex", alignItems: "center" }}>—</div>;
  }
  const W = 200, H = 40;
  const ys = data.map(d => d[valueKey]);
  const yMin = Math.min(...ys), yMax = Math.max(...ys);
  const range = (yMax - yMin) || 1;
  const px = (i) => (i / (data.length - 1)) * W;
  const py = (v) => 4 + (1 - (v - yMin) / range) * (H - 8);
  const pts = data.map((d, i) => `${px(i)},${py(d[valueKey])}`).join(" ");
  return (
    <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none"
         width="100%" height={height} style={{ display: "block" }}>
      <polyline points={pts} fill="none" stroke={color} strokeWidth="2"
        strokeLinejoin="round" strokeLinecap="round" />
      <circle cx={px(data.length - 1)} cy={py(ys[ys.length - 1])} r="3" fill={color} />
    </svg>
  );
}

// ── Trend delta helper ──────────────────────────────────────────────
function trendDelta(data, key) {
  if (!data || data.length < 2) return null;
  const recent = data.slice(-7);
  const prior  = data.slice(-14, -7);
  if (recent.length === 0 || prior.length === 0) return null;
  const avg = (arr) => arr.reduce((s, x) => s + x[key], 0) / arr.length;
  const r = avg(recent), p = avg(prior);
  return { delta: r - p, recent: r, prior: p };
}

// ── Workout card (used both sides) ───────────────────────────────────
function WorkoutCard({ workout, compact = false, onEdit, onDelete,
                      liftLog, onLogLift, onViewHistory }) {
  const meta = wt(workout.type);
  const Icon = meta.icon;
  const [open, setOpen] = useState(!compact);

  // Find the lift log entry for this workout date + exercise
  const sessionFor = (exName) => {
    if (!liftLog || !liftLog[exName]) return null;
    return liftLog[exName].find(s => s.date === workout._date) || null;
  };

  return (
    <div style={{
      background: T.card, border: `1px solid ${T.border}`,
      borderLeft: `3px solid ${meta.color}`, borderRadius: 12, overflow: "hidden",
    }}>
      <div onClick={() => compact && setOpen(o => !o)}
        style={{ padding: 14, cursor: compact ? "pointer" : "default" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
          <div style={{
            width: 32, height: 32, borderRadius: 8,
            background: `${meta.color}1a`, color: meta.color,
            display: "flex", alignItems: "center", justifyContent: "center",
          }}>
            <Icon size={16} />
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 17, letterSpacing: 1.5, color: T.text }}>
              {workout.title}
            </div>
            <div style={{ display: "flex", gap: 6, marginTop: 4, flexWrap: "wrap" }}>
              <Pill color={meta.color}>{meta.label}</Pill>
              <Pill color={T.muted}><Clock size={9} /> {workout.duration}m</Pill>
              {workout.intensity && <Pill color={T.warn}><Zap size={9} /> {workout.intensity}</Pill>}
            </div>
          </div>
          {compact && <ChevronRight size={16} color={T.muted}
            style={{ transform: open ? "rotate(90deg)" : "rotate(0)", transition: "transform 0.2s" }} />}
        </div>

        {open && (
          <>
            {workout.notes && (
              <div style={{
                background: T.surface, border: `1px solid ${T.border}`,
                borderRadius: 8, padding: "10px 12px", marginTop: 10,
                fontSize: 12, color: T.muted, fontStyle: "italic",
              }}>
                <span style={{ color: T.pacific, fontWeight: 600, fontStyle: "normal" }}>Coach&apos;s note: </span>
                {workout.notes}
              </div>
            )}

            <div style={{ marginTop: 12 }}>
              <div style={{
                fontFamily: FONT_MONO, fontSize: 9, letterSpacing: 1.5,
                color: T.muted, textTransform: "uppercase", marginBottom: 8,
              }}>Exercises</div>
              <div style={{ display: "grid", gap: 6 }}>
                {workout.exercises.map((ex, i) => {
                  const session = sessionFor(ex.name);
                  const logged = session && session.sets && session.sets.length > 0;
                  return (
                    <div key={i} style={{
                      background: T.surface, borderRadius: 8,
                      border: `1px solid ${logged ? `${T.good}55` : T.border}`,
                      overflow: "hidden",
                    }}>
                      <div style={{
                        display: "grid", gridTemplateColumns: "auto 1fr auto",
                        gap: 10, padding: "8px 12px", alignItems: "center",
                      }}>
                        <div style={{
                          width: 22, height: 22, borderRadius: 6,
                          background: T.bg, color: meta.color,
                          display: "flex", alignItems: "center", justifyContent: "center",
                          fontFamily: FONT_MONO, fontSize: 10, fontWeight: 600,
                        }}>{i + 1}</div>
                        <div style={{ minWidth: 0 }}>
                          <div style={{ fontSize: 13, color: T.text, fontWeight: 500,
                            display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                            {onViewHistory ? (
                              <button onClick={() => onViewHistory(ex.name)} type="button"
                                style={{
                                  background: "none", border: "none", padding: 0, cursor: "pointer",
                                  color: T.text, fontSize: 13, fontWeight: 500, fontFamily: "inherit",
                                  textAlign: "left", textDecoration: "underline",
                                  textDecorationColor: T.border, textUnderlineOffset: 2,
                                }}>
                                {ex.name}
                              </button>
                            ) : ex.name}
                          </div>
                          <div style={{ fontFamily: FONT_MONO, fontSize: 10, color: T.muted, marginTop: 2 }}>
                            <span style={{ opacity: 0.85 }}>Target:</span> {ex.sets}×{ex.reps}
                            {ex.load && ex.load !== "—" && <span style={{ color: T.pacific }}> · {ex.load}</span>}
                          </div>
                        </div>
                        {onLogLift ? (
                          <button onClick={() => onLogLift(ex)} type="button"
                            style={{
                              background: logged ? T.good : "transparent",
                              color: logged ? "#fff" : T.pacific,
                              border: `1px solid ${logged ? T.good : T.pacific}55`,
                              padding: "4px 10px", borderRadius: 6,
                              fontFamily: FONT_DISPLAY, fontSize: 10, letterSpacing: 1,
                              cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 4,
                            }}>
                            {logged
                              ? <><CheckCircle2 size={11} /> LOGGED</>
                              : <><Plus size={11} /> LOG</>}
                          </button>
                        ) : (
                          <Circle size={14} color={T.muted} />
                        )}
                      </div>

                      {/* Logged set summary */}
                      {logged && (
                        <div style={{
                          background: `${T.good}0d`,
                          borderTop: `1px solid ${T.good}33`,
                          padding: "6px 12px",
                        }}>
                          <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                            {session.sets.map((s, idx) => (
                              <span key={idx} style={{
                                fontFamily: FONT_MONO, fontSize: 10, color: T.textSoft,
                                background: T.card, border: `1px solid ${T.border}`,
                                padding: "2px 6px", borderRadius: 4,
                              }}>
                                {s.weight ? `${s.weight}kg` : "BW"} × {s.reps}
                                {s.rpe && <span style={{ color: T.warn }}> @{s.rpe}</span>}
                              </span>
                            ))}
                          </div>
                          {(() => {
                            const e1 = sessionBest1RM(session.sets);
                            return e1 ? (
                              <div style={{ fontFamily: FONT_MONO, fontSize: 9, color: T.muted, marginTop: 4, letterSpacing: 1 }}>
                                EST 1RM: <span style={{ color: T.pacific }}>{e1}kg</span>
                                {" · "}
                                VOLUME: <span style={{ color: T.text }}>
                                  {Math.round(sessionVolume(session.sets)).toLocaleString("en-GB")}kg
                                </span>
                              </div>
                            ) : null;
                          })()}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {(onEdit || onDelete) && (
              <div style={{ display: "flex", gap: 8, marginTop: 12, justifyContent: "flex-end" }}>
                {onEdit   && <Btn variant="ghost"  onClick={onEdit}   icon={Edit3}>Edit</Btn>}
                {onDelete && <Btn variant="danger" onClick={onDelete} icon={Trash2}>Remove</Btn>}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ────────────────────────────────────────────────────────────────────
// ATHLETE / CLIENT VIEW
// ────────────────────────────────────────────────────────────────────
function AthleteApp({ athlete, workouts, events, messages, onSendMessage, foodLog, onAddFood,
                      weightLog, moodLog, stepsLog, waterLog, sleepLog,
                      onAddWeight, onAddMood, onAddSteps, onAddWater, onAddSleep,
                      liftLog, onLogLift }) {
  const [tab, setTab] = useState("home");
  const [selectedDate, setSelectedDate] = useState(todayISO());
  const [logging, setLogging] = useState(null); // null | 'weight' | 'mood' | 'steps' | 'sleep'
  const [liftDraft, setLiftDraft] = useState(null);  // { exercise, date, existing } | null
  const [historyFor, setHistoryFor] = useState(null); // exercise name to view history of

  const today = todayISO();
  const todayWorkout = workouts[today] || null;

  // Today's macro totals from the food log
  const todayMacros = (foodLog || []).reduce((a, f) => ({
    calories: a.calories + (f.calories || 0),
    protein:  a.protein  + (f.protein  || 0),
    carbs:    a.carbs    + (f.carbs    || 0),
    fat:      a.fat      + (f.fat      || 0),
  }), { calories: 0, protein: 0, carbs: 0, fat: 0 });

  // Open the lift logger for a given exercise on a given date
  const openLiftFor = (date) => (ex) => {
    const existing = liftLog && liftLog[ex.name]
      ? (liftLog[ex.name].find(s => s.date === date) || null)
      : null;
    setLiftDraft({ exercise: ex, date, existing });
  };

  return (
    <div style={{ minHeight: "100vh", background: T.bg, color: T.text, fontFamily: FONT_BODY, position: "relative" }}>
      <TribalWatermark />
      <div style={{ position: "relative", zIndex: 1 }}>
        <AthleteTopBar athlete={athlete} />

        <div style={{ maxWidth: 720, margin: "0 auto", padding: "20px 16px 100px" }}>
          {tab === "home"     && <AthleteHome athlete={athlete} todayWorkout={todayWorkout}
                                              todayMacros={todayMacros} setTab={setTab}
                                              weightLog={weightLog} moodLog={moodLog}
                                              stepsLog={stepsLog} waterLog={waterLog} sleepLog={sleepLog}
                                              onLogWeight={() => setLogging("weight")}
                                              onLogMood={() => setLogging("mood")}
                                              onLogSteps={() => setLogging("steps")}
                                              onLogSleep={() => setLogging("sleep")}
                                              onAddWater={onAddWater}
                                              liftLog={liftLog}
                                              onLogLift={openLiftFor(today)}
                                              onViewHistory={(name) => setHistoryFor(name)} />}
          {tab === "calendar" && <AthleteCalendar workouts={workouts} events={events}
                                                  selectedDate={selectedDate} setSelectedDate={setSelectedDate}
                                                  liftLog={liftLog}
                                                  onLogLift={openLiftFor(selectedDate)}
                                                  onViewHistory={(name) => setHistoryFor(name)} />}
          {tab === "macros"   && <AthleteMacros targets={athlete.targets} todayMacros={todayMacros}
                                                foodLog={foodLog} onAddFood={onAddFood} />}
          {tab === "library"  && <ExerciseLibrary />}
          {tab === "inbox"    && <AthleteInbox messages={messages} onSend={onSendMessage} />}
        </div>

        <AthleteTabBar tab={tab} setTab={setTab} />

        {logging === "weight" && (
          <WeightLogModal
            lastWeight={weightLog && weightLog.length ? weightLog[weightLog.length - 1].weight : athlete.weight}
            onCancel={() => setLogging(null)}
            onSave={(entry) => { onAddWeight(entry); setLogging(null); }}
          />
        )}
        {logging === "mood" && (
          <MoodLogModal
            onCancel={() => setLogging(null)}
            onSave={(entry) => { onAddMood(entry); setLogging(null); }}
          />
        )}
        {logging === "steps" && (
          <StepsLogModal
            todaySteps={(stepsLog || []).find(s => s.date === todayISO())}
            onCancel={() => setLogging(null)}
            onSave={(entry) => { onAddSteps(entry); setLogging(null); }}
          />
        )}
        {logging === "sleep" && (
          <SleepLogModal
            onCancel={() => setLogging(null)}
            onSave={(entry) => { onAddSleep(entry); setLogging(null); }}
          />
        )}
        {liftDraft && (
          <LiftLogModal
            exercise={liftDraft.exercise}
            date={liftDraft.date}
            existing={liftDraft.existing}
            history={liftLog && liftLog[liftDraft.exercise.name] ? liftLog[liftDraft.exercise.name] : []}
            onCancel={() => setLiftDraft(null)}
            onSave={(entry) => { onLogLift(liftDraft.exercise.name, entry); setLiftDraft(null); }}
          />
        )}
        {historyFor && (
          <LiftHistoryModal
            exerciseName={historyFor}
            history={liftLog && liftLog[historyFor] ? liftLog[historyFor] : []}
            onClose={() => setHistoryFor(null)}
          />
        )}
      </div>
    </div>
  );
}

