    steps:  { logs: stepsLog,  color: T.good,    key: "steps",  unit: "",    fixed: 0, label: "STEPS",
              formatY: (v) => v >= 1000 ? `${(v / 1000).toFixed(1)}k` : Math.round(v).toString() },
