function AthleteCalendar({ workouts, events, selectedDate, setSelectedDate,
                           liftLog, onLogLift, onViewHistory }) {
  // 14-day strip (today + 13)
  const days = Array.from({ length: 14 }, (_, i) => dateOffset(i));
  const dayWorkout = workouts[selectedDate];
  const dayEvents = (events || []).filter(e => e.date === selectedDate);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <div>
        <div style={{ fontFamily: FONT_MONO, fontSize: 10, letterSpacing: 2, color: T.pacific }}>YOUR PROGRAM</div>
        <div style={{ fontFamily: FONT_DISPLAY, fontSize: 30, letterSpacing: 2, marginTop: 4 }}>NEXT 14 DAYS</div>
      </div>

      {/* Day strip */}
      <div style={{ display: "flex", gap: 8, overflowX: "auto", paddingBottom: 8,
        scrollSnapType: "x mandatory" }}>
        {days.map(d => {
          const date = new Date(d);
          const wk = workouts[d];
          const evs = (events || []).filter(e => e.date === d);
          const isSel = d === selectedDate;
          const isToday = d === todayISO();
          return (
            <button key={d} onClick={() => setSelectedDate(d)} type="button"
              style={{
                background: isSel ? T.pacific : T.card,
                border: `1px solid ${isSel ? T.pacific : T.border}`,
                color: isSel ? T.bgDeep : T.text,
                borderRadius: 12, padding: "10px 4px", minWidth: 64,
                cursor: "pointer", scrollSnapAlign: "start",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
                position: "relative",
              }}>
              <div style={{ fontFamily: FONT_MONO, fontSize: 9, letterSpacing: 1,
                color: isSel ? T.bgDeep : T.muted }}>
                {date.toLocaleDateString("en-GB", { weekday: "short" }).toUpperCase()}
              </div>
              <div style={{ fontFamily: FONT_DISPLAY, fontSize: 22, letterSpacing: 1 }}>
                {date.getDate()}
              </div>
              <div style={{ display: "flex", gap: 3, height: 6 }}>
                {wk && <div style={{ width: 5, height: 5, borderRadius: "50%",
                  background: isSel ? T.bgDeep : wt(wk.type).color }} />}
                {evs.length > 0 && <div style={{ width: 5, height: 5, borderRadius: "50%",
                  background: isSel ? T.bgDeep : T.warn }} />}
              </div>
              {isToday && !isSel && (
                <div style={{ position: "absolute", top: 4, right: 4, width: 6, height: 6,
                  borderRadius: "50%", background: T.pacific }} />
              )}
            </button>
          );
        })}
      </div>

      {/* Selected day content */}
      <div>
        <div style={{ fontFamily: FONT_MONO, fontSize: 10, letterSpacing: 1.5, color: T.muted,
          textTransform: "uppercase", marginBottom: 10 }}>
          {new Date(selectedDate).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long" })}
        </div>

        {dayWorkout ? (
          <WorkoutCard
            workout={{ ...dayWorkout, _date: selectedDate }}
            liftLog={liftLog}
            onLogLift={onLogLift}
            onViewHistory={onViewHistory}
          />
        ) : (
          <Card style={{ textAlign: "center", padding: 30 }}>
            <Calendar size={26} color={T.muted} style={{ marginBottom: 8 }} />
            <div style={{ color: T.muted, fontSize: 13 }}>No workout programmed</div>
          </Card>
        )}

        {dayEvents.length > 0 && (
          <div style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 8 }}>
            {dayEvents.map(ev => (
              <Card key={ev.id} style={{ borderLeft: `3px solid ${T.warn}`, padding: 12 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <Calendar size={14} color={T.warn} />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14, letterSpacing: 1, color: T.text }}>
                      {ev.title.toUpperCase()}
                    </div>
                    {ev.notes && <div style={{ color: T.muted, fontSize: 12, marginTop: 2 }}>{ev.notes}</div>}
                  </div>
                  {ev.time && <Pill color={T.warn}>{ev.time}</Pill>}
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

