// ── Barcode Scanner — uses BarcodeDetector if available, simulated fallback ─
function BarcodeScanner({ onDetected, onClose }) {
  const [status, setStatus] = useState("starting"); // starting | scanning | error | unsupported
  const [errMsg, setErrMsg] = useState("");
  const [supported, setSupported] = useState(false);
  const videoRef = useRef(null);

  useEffect(() => {
    let stream = null;
    let detector = null;
    let raf = null;
    let cancelled = false;

    const start = async () => {
      try {
        const hasDetector = typeof window !== "undefined" && "BarcodeDetector" in window;
        setSupported(hasDetector);

        if (!navigator.mediaDevices?.getUserMedia) {
          setStatus("error");
          setErrMsg("Camera not available on this device or browser.");
          return;
        }

        stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: { ideal: "environment" } },
          audio: false,
        });
        if (cancelled) { stream.getTracks().forEach(t => t.stop()); return; }
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play().catch(() => {});
        }
        setStatus("scanning");

        if (hasDetector) {
          detector = new window.BarcodeDetector({
            formats: ["ean_13", "ean_8", "upc_a", "upc_e", "code_128", "code_39", "qr_code"],
          });
          const tick = async () => {
            if (cancelled || !videoRef.current) return;
            try {
              const codes = await detector.detect(videoRef.current);
              if (codes && codes.length > 0) {
                const code = codes[0].rawValue;
                cancelled = true;
                stream?.getTracks().forEach(t => t.stop());
                onDetected(code);
                return;
              }
            } catch { /* ignore frame errors */ }
            raf = requestAnimationFrame(tick);
          };
          raf = requestAnimationFrame(tick);
        }
      } catch (e) {
        setStatus("error");
        setErrMsg(e.message || "Could not access camera.");
      }
    };
    start();
    return () => {
      cancelled = true;
      if (raf) cancelAnimationFrame(raf);
      if (stream) stream.getTracks().forEach(t => t.stop());
    };
  }, [onDetected]);

  // Demo fallback: pick a sample barcode
  const demoCodes = Object.keys(FOOD_BY_BARCODE);
  const simulate = () => onDetected(demoCodes[Math.floor(Math.random() * demoCodes.length)]);

  return (
    <Modal onClose={onClose} title="Scan Barcode">
      <div style={{
        position: "relative", aspectRatio: "1 / 1", background: "#000",
        borderRadius: 12, overflow: "hidden", border: `1px solid ${T.border}`,
      }}>
        <video ref={videoRef} playsInline muted
          style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />

        {/* Scan overlay */}
        <div style={{ position: "absolute", inset: 0, display: "flex",
          alignItems: "center", justifyContent: "center", pointerEvents: "none" }}>
          <div style={{
            width: "75%", height: "45%", borderRadius: 14,
            border: `2px solid ${T.pacific}`,
            boxShadow: `0 0 0 9999px rgba(0,0,0,0.55)`,
            position: "relative",
          }}>
            <div style={{
              position: "absolute", top: "50%", left: 0, right: 0, height: 2,
              background: T.pacific,
              boxShadow: `0 0 12px ${T.pacific}`,
              animation: "fp-scan-line 1.6s ease-in-out infinite",
            }} />
          </div>
        </div>

        {/* Status banner */}
        <div style={{
          position: "absolute", top: 10, left: 10, right: 10,
          background: "rgba(0,0,0,0.65)", color: "#fff", padding: "8px 12px",
          borderRadius: 8, fontFamily: FONT_MONO, fontSize: 11, letterSpacing: 1,
          display: "flex", alignItems: "center", gap: 8,
        }}>
          {status === "starting" && <>● STARTING CAMERA…</>}
          {status === "scanning" && supported && <><span style={{ color: T.pacific }}>●</span> SCANNING — POINT AT BARCODE</>}
          {status === "scanning" && !supported && <><span style={{ color: T.warn }}>●</span> CAMERA ON · DETECTOR UNAVAILABLE</>}
          {status === "error" && <><span style={{ color: T.danger }}>●</span> ERROR</>}
        </div>
      </div>

      {status === "error" && (
        <div style={{ background: `${T.danger}10`, color: T.danger, padding: 12,
          borderRadius: 8, marginTop: 12, fontSize: 12 }}>
          {errMsg}
        </div>
      )}

      {status === "scanning" && !supported && (
        <div style={{ background: `${T.warn}10`, color: T.textSoft, padding: 12,
          borderRadius: 8, marginTop: 12, fontSize: 12, lineHeight: 1.5 }}>
          Your browser doesn&apos;t support live barcode detection. Use a recent version of
          Chrome on Android, or use the simulator below for a demo.
        </div>
      )}

      <style>{`@keyframes fp-scan-line {
        0% { top: 5%; } 50% { top: 92%; } 100% { top: 5%; }
      }`}</style>

      <div style={{ display: "flex", gap: 8, marginTop: 14, justifyContent: "space-between" }}>
        <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
        <Btn variant="quiet" icon={ScanLine} onClick={simulate}>
          Simulate Scan (demo)
        </Btn>
      </div>
    </Modal>
  );
}

