// ── Add food modal — confirm portion & meal ────────────────────────────
function AddFoodModal({ food, onCancel, onSave }) {
  const [name, setName] = useState(food.name || "");
  const [grams, setGrams] = useState(food.serving || 100);
  const [meal, setMeal] = useState("Lunch");
  const ratio = food.serving ? grams / food.serving : 1;
  const scaled = {
    calories: Math.round((food.calories || 0) * ratio),
    protein:  Math.round((food.protein  || 0) * ratio * 10) / 10,
    carbs:    Math.round((food.carbs    || 0) * ratio * 10) / 10,
    fat:      Math.round((food.fat      || 0) * ratio * 10) / 10,
  };
  // Manual fields when no DB hit
  const [manC, setManC] = useState(food.calories || 0);
  const [manP, setManP] = useState(food.protein  || 0);
  const [manB, setManB] = useState(food.carbs    || 0);
  const [manF, setManF] = useState(food.fat      || 0);
  const isManual = !food.serving || food._unknown;

  const save = () => {
    if (!name.trim()) return;
    onSave({
      id: `f-${Date.now()}`,
      name: name.trim(),
      meal,
      calories: isManual ? Number(manC) : scaled.calories,
      protein:  isManual ? Number(manP) : scaled.protein,
      carbs:    isManual ? Number(manB) : scaled.carbs,
      fat:      isManual ? Number(manF) : scaled.fat,
    });
  };

  return (
    <Modal onClose={onCancel} title={food._unknown ? "Unknown Barcode" : "Confirm Item"}>
      {food._barcode && (
        <div style={{ marginBottom: 12, padding: 10, background: T.surface,
          border: `1px solid ${T.border}`, borderRadius: 8,
          display: "flex", alignItems: "center", gap: 10 }}>
          <ScanLine size={16} color={T.pacific} />
          <div>
            <div style={{ fontFamily: FONT_MONO, fontSize: 11, color: T.text, letterSpacing: 1 }}>
              {food._barcode}
            </div>
            {food._unknown && <div style={{ fontSize: 11, color: T.warn, marginTop: 2 }}>
              Not in our database — fill in details below.
            </div>}
          </div>
        </div>
      )}

      <div style={{ display: "grid", gap: 12 }}>
        <Field label="Item name">
          <Input value={name} onChange={(e) => setName(e.target.value)} />
        </Field>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="Meal">
            <Select value={meal} onChange={(e) => setMeal(e.target.value)}
              options={["Breakfast", "Lunch", "Dinner", "Snack"].map(m => ({ value: m, label: m }))} />
          </Field>
          {!isManual && (
            <Field label={`Portion (${food.servingUnit || "g"})`}>
              <Input type="number" value={grams}
                onChange={(e) => setGrams(parseFloat(e.target.value) || 0)} />
            </Field>
          )}
        </div>

        {isManual ? (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 8 }}>
            <Field label="kcal"><Input type="number" value={manC} onChange={(e) => setManC(e.target.value)} /></Field>
            <Field label="P (g)"><Input type="number" value={manP} onChange={(e) => setManP(e.target.value)} /></Field>
            <Field label="C (g)"><Input type="number" value={manB} onChange={(e) => setManB(e.target.value)} /></Field>
            <Field label="F (g)"><Input type="number" value={manF} onChange={(e) => setManF(e.target.value)} /></Field>
          </div>
        ) : (
          <div style={{ background: T.surface, border: `1px solid ${T.border}`,
            borderRadius: 10, padding: 12 }}>
            <div style={{ fontFamily: FONT_MONO, fontSize: 9, letterSpacing: 1.5,
              color: T.muted, textTransform: "uppercase", marginBottom: 8 }}>Macros for {grams}{food.servingUnit}</div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 6, textAlign: "center" }}>
              {[
                { k: "kcal",    v: scaled.calories, c: T.calories },
                { k: "protein", v: `${scaled.protein}g`, c: T.protein },
                { k: "carbs",   v: `${scaled.carbs}g`,   c: T.carbs },
                { k: "fat",     v: `${scaled.fat}g`,     c: T.fat },
              ].map(s => (
                <div key={s.k}>
                  <div style={{ fontFamily: FONT_DISPLAY, fontSize: 18, color: s.c }}>{s.v}</div>
                  <div style={{ fontFamily: FONT_MONO, fontSize: 9, color: T.muted, letterSpacing: 1 }}>{s.k.toUpperCase()}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
          <Btn variant="ghost" onClick={onCancel}>Cancel</Btn>
          <Btn icon={Save} onClick={save} disabled={!name.trim()}>Add to Log</Btn>
        </div>
      </div>
    </Modal>
  );
}

