// ── Coach Trends — view-only weight & mood charts ────────────────────
function CoachTrendsView({ weightLog, moodLog, stepsLog, waterLog, sleepLog }) {
  const [range, setRange] = useState(30);

  const sliced = (log) => [...(log || [])].sort((a, b) => a.date.localeCompare(b.date)).slice(-range);
  const sortedW = sliced(weightLog);
  const sortedM = sliced(moodLog);
  const sortedS = sliced(stepsLog);
  const sortedH = sliced(waterLog);
  const sortedSl = sliced(sleepLog);

  const RangeBtn = ({ days }) => (
    <button onClick={() => setRange(days)} type="button"
      style={{
        background: range === days ? T.pacific : "transparent",
        color: range === days ? "#fff" : T.muted,
        border: `1px solid ${range === days ? T.pacific : T.border}`,
        padding: "6px 12px", borderRadius: 6,
        fontFamily: FONT_MONO, fontSize: 11, letterSpacing: 1, cursor: "pointer",
      }}>{days}D</button>
  );

  const recentMoodNotes = [...(moodLog || [])]
    .filter(m => m.note && m.note.trim())
    .sort((a, b) => b.date.localeCompare(a.date))
    .slice(0, 5);

  const allEmpty = sortedW.length === 0 && sortedM.length === 0
                && sortedS.length === 0 && sortedH.length === 0 && sortedSl.length === 0;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 18 }}>
      <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
        <RangeBtn days={7} />
        <RangeBtn days={14} />
        <RangeBtn days={30} />
      </div>

      {/* Weight */}
      <CoachMetricCard
        icon={Scale} title="WEIGHT" color={T.pacific} data={sortedW} valueKey="weight"
        unit=" kg" fixed={1} range={range}
        formatLatest={(v) => (
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 28, color: T.text, letterSpacing: 1 }}>
            {v.toFixed(1)}<span style={{ fontSize: 14, color: T.muted, marginLeft: 4 }}>kg</span>
          </div>
        )}
        deltaFmt={(d) => `${d > 0 ? "+" : ""}${d.toFixed(2)} kg vs prev. week`}
        deltaColor={(d) => d < 0 ? T.good : T.warn}
      />

      {/* Mood */}
      {sortedM.length > 0 ? (
        <Card>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <Heart size={16} color={T.clay} />
              <div>
                <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, letterSpacing: 2, color: T.text }}>MOOD</div>
                <div style={{ fontSize: 11, color: T.muted, marginTop: 2 }}>
                  {sortedM.length} entr{sortedM.length === 1 ? "y" : "ies"} in last {range} days
                </div>
              </div>
            </div>
            {(() => {
              const latest = sortedM[sortedM.length - 1];
              const m = moodMeta(latest.score);
              const I = m.icon;
              const avg = sortedM.reduce((s, x) => s + x.score, 0) / sortedM.length;
              return (
                <div style={{ textAlign: "right", display: "flex", alignItems: "center", gap: 10 }}>
                  <div>
                    <div style={{ fontFamily: FONT_MONO, fontSize: 9, color: T.muted, letterSpacing: 1, textAlign: "right" }}>
                      AVG {avg.toFixed(1)}
                    </div>
                    <div style={{ fontFamily: FONT_DISPLAY, fontSize: 18, color: m.color, letterSpacing: 1.5 }}>
                      {m.label.toUpperCase()}
                    </div>
                  </div>
                  <I size={32} color={m.color} />
                </div>
              );
            })()}
          </div>
          <LineChart data={sortedM} color={T.clay} valueKey="score" unit="/5" fixed={1}
            yMin={1} yMax={5} height={180} />
        </Card>
      ) : null}

      {/* Steps */}
      <CoachMetricCard
        icon={Footprints} title="STEPS" color={T.good} data={sortedS} valueKey="steps"
        unit="" fixed={0} range={range}
        formatY={(v) => v >= 1000 ? `${(v / 1000).toFixed(1)}k` : Math.round(v).toString()}
        formatLatest={(v) => (
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 28, color: T.text, letterSpacing: 1 }}>
            {Math.round(v).toLocaleString("en-GB")}
            <span style={{ fontSize: 12, color: T.muted, marginLeft: 4 }}>steps</span>
          </div>
        )}
        deltaFmt={(d) => `${d > 0 ? "+" : ""}${Math.round(d).toLocaleString("en-GB")} avg vs prev. week`}
        deltaColor={(d) => d > 0 ? T.good : T.warn}
        avgFooter={(arr) => `Daily avg: ${Math.round(arr.reduce((s, x) => s + x.steps, 0) / arr.length).toLocaleString("en-GB")} steps`}
      />

      {/* Water */}
      <CoachMetricCard
        icon={Droplet} title="WATER" color={T.carbs} data={sortedH} valueKey="ml"
        unit="ml" fixed={0} range={range}
        formatY={(v) => `${(v / 1000).toFixed(1)}L`}
        formatLatest={(v) => (
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 28, color: T.text, letterSpacing: 1 }}>
            {(v / 1000).toFixed(2)}<span style={{ fontSize: 14, color: T.muted, marginLeft: 4 }}>L</span>
          </div>
        )}
        deltaFmt={(d) => `${d > 0 ? "+" : ""}${(d / 1000).toFixed(2)}L avg vs prev. week`}
        deltaColor={(d) => d > 0 ? T.good : T.warn}
        avgFooter={(arr) => `Daily avg: ${(arr.reduce((s, x) => s + x.ml, 0) / arr.length / 1000).toFixed(2)}L`}
      />

      {/* Sleep */}
      <CoachMetricCard
        icon={Moon} title="SLEEP" color={T.fat} data={sortedSl} valueKey="hours"
        unit="h" fixed={1} range={range} yMin={0} yMax={12}
        formatLatest={(v) => {
          const latest = sortedSl[sortedSl.length - 1];
          return (
            <div>
              <div style={{ fontFamily: FONT_DISPLAY, fontSize: 28, color: T.text, letterSpacing: 1 }}>
                {v.toFixed(1)}<span style={{ fontSize: 14, color: T.muted, marginLeft: 4 }}>h</span>
              </div>
              {latest && (
                <div style={{ fontFamily: FONT_MONO, fontSize: 10, color: T.fat, letterSpacing: 1, marginTop: 2 }}>
                  Quality {"★".repeat(latest.quality)}{"☆".repeat(5 - latest.quality)}
                </div>
              )}
            </div>
          );
        }}
        deltaFmt={(d) => `${d > 0 ? "+" : ""}${d.toFixed(2)}h avg vs prev. week`}
        deltaColor={(d) => d > 0 ? T.good : T.warn}
        avgFooter={(arr) => {
          const avgQ = arr.reduce((s, x) => s + x.quality, 0) / arr.length;
          return `Avg quality ${avgQ.toFixed(1)}/5 · ${(arr.reduce((s, x) => s + x.hours, 0) / arr.length).toFixed(1)}h/night`;
        }}
      />

      {/* Recent mood notes */}
      {recentMoodNotes.length > 0 && (
        <Card>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14, letterSpacing: 2, color: T.text, marginBottom: 12 }}>
            RECENT NOTES
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {recentMoodNotes.map((n, i) => {
              const m = moodMeta(n.score);
              const I = m.icon;
              return (
                <div key={i} style={{
                  display: "flex", gap: 12, alignItems: "flex-start",
                  padding: 12, background: T.surface, borderRadius: 10,
                  border: `1px solid ${T.border}`,
                }}>
                  <I size={20} color={m.color} style={{ flexShrink: 0, marginTop: 2 }} />
                  <div style={{ flex: 1 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                      <Pill color={m.color}>{m.label}</Pill>
                      <span style={{ fontFamily: FONT_MONO, fontSize: 10, color: T.muted }}>
                        {new Date(n.date).toLocaleDateString("en-GB", { day: "numeric", month: "short" })}
                      </span>
                    </div>
                    <div style={{ fontSize: 13, color: T.textSoft, lineHeight: 1.4 }}>{n.note}</div>
                  </div>
                </div>
              );
            })}
          </div>
        </Card>
      )}

      {allEmpty && (
        <Card style={{ textAlign: "center", padding: 40 }}>
          <LineChartIcon size={32} color={T.muted} style={{ marginBottom: 10 }} />
          <div style={{ color: T.muted, fontSize: 13 }}>
            No tracking data yet. Charts will appear here as the athlete logs entries.
          </div>
        </Card>
      )}
    </div>
  );
}

// Reusable metric section for the coach trends view
function CoachMetricCard({ icon: Icon, title, color, data, valueKey, unit, fixed, range,
                           formatY, formatLatest, deltaFmt, deltaColor, avgFooter,
                           yMin, yMax }) {
  if (!data || data.length === 0) return null;
  const latest = data[data.length - 1][valueKey];
  const td = trendDelta(data, valueKey);

  return (
    <Card>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 14 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <Icon size={16} color={color} />
          <div>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, letterSpacing: 2, color: T.text }}>{title}</div>
            <div style={{ fontSize: 11, color: T.muted, marginTop: 2 }}>
              {data.length} entr{data.length === 1 ? "y" : "ies"} in last {range} days
            </div>
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          {formatLatest ? formatLatest(latest) : (
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 28, color: T.text, letterSpacing: 1 }}>
              {Number(latest).toFixed(fixed)}{unit && <span style={{ fontSize: 14, color: T.muted, marginLeft: 4 }}>{unit}</span>}
            </div>
          )}
          {td && Math.abs(td.delta) >= (fixed === 0 ? 1 : 0.05) && deltaFmt && (
            <div style={{ display: "flex", alignItems: "center", gap: 4, justifyContent: "flex-end",
              color: deltaColor ? deltaColor(td.delta) : T.muted, fontSize: 11, marginTop: 2 }}>
              {td.delta > 0 ? <TrendingUp size={11} /> : <TrendingDown size={11} />}
              {deltaFmt(td.delta)}
            </div>
          )}
        </div>
      </div>
      <LineChart data={data} color={color} valueKey={valueKey} unit={unit} fixed={fixed}
        formatY={formatY} yMin={yMin} yMax={yMax} height={180} />
      {avgFooter && data.length > 0 && (
        <div style={{
          fontFamily: FONT_MONO, fontSize: 10, letterSpacing: 1, color: T.muted,
          marginTop: 10, paddingTop: 10, borderTop: `1px solid ${T.border}`,
        }}>
          {avgFooter(data)}
        </div>
      )}
    </Card>
  );
}

// ── Coach Strength View — view all tracked lifts and their progression ──
function CoachStrengthView({ liftLog }) {
  const [selectedExercise, setSelectedExercise] = useState(null);

  const exerciseNames = Object.keys(liftLog || {}).filter(name => (liftLog[name] || []).length > 0);

  if (exerciseNames.length === 0) {
    return (
      <Card style={{ textAlign: "center", padding: 40 }}>
        <Trophy size={32} color={T.muted} style={{ marginBottom: 10 }} />
        <div style={{ color: T.muted, fontSize: 13 }}>
          No lifts logged yet. The athlete&apos;s logged sets will appear here.
        </div>
      </Card>
    );
  }

  // Sort by most recently logged
  const sortedNames = exerciseNames.sort((a, b) => {
    const aLast = liftLog[a].slice().sort((x, y) => x.date.localeCompare(y.date));
    const bLast = liftLog[b].slice().sort((x, y) => x.date.localeCompare(y.date));
    return bLast[bLast.length - 1].date.localeCompare(aLast[aLast.length - 1].date);
  });

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      <div style={{ fontFamily: FONT_MONO, fontSize: 10, letterSpacing: 1.5,
        color: T.muted, textTransform: "uppercase" }}>
        {exerciseNames.length} tracked {exerciseNames.length === 1 ? "lift" : "lifts"}
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {sortedNames.map(name => {
          const sessions = [...liftLog[name]].sort((a, b) => a.date.localeCompare(b.date));
          const chartData = sessions
            .map(s => ({ date: s.date, e1rm: sessionBest1RM(s.sets) }))
            .filter(d => d.e1rm !== null);
          const pr = chartData.length ? Math.max(...chartData.map(d => d.e1rm)) : null;
          const latest = sessions[sessions.length - 1];
          const latest1RM = sessionBest1RM(latest.sets);
          const td = trendDelta(chartData, "e1rm");
          const isProgressing = td && td.delta > 0.1;
          const isStalling = td && Math.abs(td.delta) < 0.5 && chartData.length >= 3;
          const isRegressing = td && td.delta < -0.5;

          return (
            <button key={name} onClick={() => setSelectedExercise(name)} type="button"
              style={{
                background: T.card, border: `1px solid ${T.border}`,
                borderLeft: `3px solid ${isRegressing ? T.warn : isProgressing ? T.good : T.pacific}`,
                borderRadius: 10, padding: 14, cursor: "pointer",
                textAlign: "left", width: "100%", boxShadow: T.shadow,
              }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
                <div>
                  <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, letterSpacing: 1.5, color: T.text }}>
                    {name.toUpperCase()}
                  </div>
                  <div style={{ display: "flex", gap: 6, marginTop: 4, flexWrap: "wrap", alignItems: "center" }}>
                    <Pill color={T.pacific}>
                      <Trophy size={9} /> PR {pr}kg
                    </Pill>
                    <Pill color={T.muted}>
                      {sessions.length} session{sessions.length === 1 ? "" : "s"}
                    </Pill>
                    {isProgressing && <Pill color={T.good}><TrendingUp size={9} /> Progressing</Pill>}
                    {isStalling   && <Pill color={T.warn}>Stalling</Pill>}
                    {isRegressing && <Pill color={T.danger}><TrendingDown size={9} /> Down</Pill>}
                  </div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontFamily: FONT_MONO, fontSize: 9, letterSpacing: 1,
                    color: T.muted, textTransform: "uppercase" }}>Latest e1RM</div>
                  <div style={{ fontFamily: FONT_DISPLAY, fontSize: 22, color: T.text, lineHeight: 1.1 }}>
                    {latest1RM}<span style={{ fontSize: 11, color: T.muted, marginLeft: 2 }}>kg</span>
                  </div>
                  <div style={{ fontFamily: FONT_MONO, fontSize: 9, color: T.muted, marginTop: 2 }}>
                    {new Date(latest.date).toLocaleDateString("en-GB", { day: "numeric", month: "short" })}
                  </div>
                </div>
              </div>

              {/* Inline mini-chart preview */}
              {chartData.length >= 2 && (
                <div style={{ marginTop: 4 }}>
                  <Sparkline data={chartData} color={T.pacific} valueKey="e1rm" height={40} />
                </div>
              )}

              {/* Latest session sets */}
              <div style={{ display: "flex", flexWrap: "wrap", gap: 4, marginTop: 8 }}>
                {latest.sets.slice(0, 6).map((s, idx) => (
                  <span key={idx} style={{
                    fontFamily: FONT_MONO, fontSize: 10, color: T.textSoft,
                    background: T.surface, border: `1px solid ${T.border}`,
                    padding: "2px 6px", borderRadius: 4,
                  }}>
                    {s.weight ? `${s.weight}kg` : "BW"} × {s.reps}
                    {s.rpe && <span style={{ color: T.warn }}> @{s.rpe}</span>}
                  </span>
                ))}
                {latest.sets.length > 6 && (
                  <span style={{ fontFamily: FONT_MONO, fontSize: 10, color: T.muted, padding: "2px 6px" }}>
                    +{latest.sets.length - 6}
                  </span>
                )}
              </div>
            </button>
          );
        })}
      </div>

      {selectedExercise && (
        <LiftHistoryModal
          exerciseName={selectedExercise}
          history={liftLog[selectedExercise] || []}
          onClose={() => setSelectedExercise(null)}
        />
      )}
    </div>
  );
}

// THE NEW WORKOUT SCHEDULER — coach side
function WorkoutScheduler({ workouts, setWorkouts }) {
  const [editing, setEditing] = useState(null); // null | 'new' | dateString
  const [draft, setDraft] = useState(null);

  const startNew = (date) => {
    setDraft({
      date: date || todayISO(),
      title: "", type: "strength", duration: 45, intensity: "Moderate", notes: "",
      exercises: [{ name: "", sets: 3, reps: "8", load: "" }],
    });
    setEditing("new");
  };

  const startEdit = (date) => {
    const w = workouts[date];
    setDraft({ ...w, date, exercises: [...w.exercises] });
    setEditing(date);
  };

  const cancel = () => { setDraft(null); setEditing(null); };

  const save = () => {
    if (!draft.title.trim() || !draft.date) return;
    const id = draft.id || `w-${Date.now()}`;
    setWorkouts(prev => {
      const next = { ...prev };
      // If date changed during edit, remove old key
      if (editing !== "new" && editing !== draft.date) delete next[editing];
      next[draft.date] = {
        id,
        title: draft.title.trim(),
        type: draft.type,
        duration: parseInt(draft.duration) || 0,
        intensity: draft.intensity,
        notes: draft.notes.trim(),
        exercises: draft.exercises.filter(e => e.name.trim()),
      };
      return next;
    });
    cancel();
  };

  const remove = (date) => {
    if (!confirm(`Remove workout on ${date}?`)) return;
    setWorkouts(prev => {
      const n = { ...prev }; delete n[date]; return n;
    });
  };

  const updateEx = (i, key, val) => {
    setDraft(d => ({ ...d, exercises: d.exercises.map((e, idx) => idx === i ? { ...e, [key]: val } : e) }));
  };
  const addEx = () => setDraft(d => ({ ...d, exercises: [...d.exercises, { name: "", sets: 3, reps: "8", load: "" }] }));
  const removeEx = (i) => setDraft(d => ({ ...d, exercises: d.exercises.filter((_, idx) => idx !== i) }));

  const sortedDates = Object.keys(workouts).sort();

  return (
    <div style={{ display: "grid", gridTemplateColumns: editing ? "1fr 1fr" : "1fr", gap: 20 }}>
      {/* Left: list of programmed workouts */}
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <span style={{ fontFamily: FONT_DISPLAY, fontSize: 16, letterSpacing: 2, color: T.text }}>
            PROGRAMMED WORKOUTS
          </span>
          {!editing && <Btn icon={Plus} onClick={() => startNew()}>Add Workout</Btn>}
        </div>

        {sortedDates.length === 0 ? (
          <Card style={{ textAlign: "center", padding: 40 }}>
            <Dumbbell size={32} color={T.muted} style={{ marginBottom: 10 }} />
            <div style={{ color: T.muted, fontSize: 13 }}>
              No workouts scheduled yet.
            </div>
            <div style={{ color: T.muted, fontSize: 12, marginTop: 4 }}>
              Click <strong style={{ color: T.pacific }}>Add Workout</strong> to program the first one.
            </div>
          </Card>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {sortedDates.map(date => {
              const w = workouts[date];
              const isPast = date < todayISO();
              return (
                <div key={date} style={{ position: "relative" }}>
                  <div style={{
                    display: "flex", gap: 10, alignItems: "stretch",
                  }}>
                    <div style={{
                      background: T.surface, border: `1px solid ${T.border}`,
                      borderRadius: 10, padding: "8px 12px", textAlign: "center",
                      minWidth: 64,
                      display: "flex", flexDirection: "column", justifyContent: "center",
                      opacity: isPast ? 0.5 : 1,
                    }}>
                      <div style={{ fontFamily: FONT_MONO, fontSize: 9, color: T.pacific, letterSpacing: 1 }}>
                        {new Date(date).toLocaleDateString("en-GB", { weekday: "short" }).toUpperCase()}
                      </div>
                      <div style={{ fontFamily: FONT_DISPLAY, fontSize: 22, color: T.text, lineHeight: 1, marginTop: 2 }}>
                        {new Date(date).getDate()}
                      </div>
                      <div style={{ fontFamily: FONT_MONO, fontSize: 9, color: T.muted, letterSpacing: 1 }}>
                        {new Date(date).toLocaleDateString("en-GB", { month: "short" }).toUpperCase()}
                      </div>
                    </div>
                    <div style={{ flex: 1 }}>
                      <WorkoutCard workout={w} compact={true}
                        onEdit={() => startEdit(date)}
                        onDelete={() => remove(date)} />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Right: editor */}
      {editing && draft && (
        <Card style={{ position: "sticky", top: 100, alignSelf: "start" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
            <span style={{ fontFamily: FONT_DISPLAY, fontSize: 16, letterSpacing: 2, color: T.pacific }}>
              {editing === "new" ? "NEW WORKOUT" : "EDIT WORKOUT"}
            </span>
            <button onClick={cancel} type="button"
              style={{ background: "none", border: "none", color: T.muted, cursor: "pointer" }}>
              <X size={18} />
            </button>
          </div>

          <div style={{ display: "grid", gap: 12 }}>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <Field label="Date">
                <Input type="date" value={draft.date}
                  onChange={(e) => setDraft({ ...draft, date: e.target.value })} />
              </Field>
              <Field label="Type">
                <Select value={draft.type}
                  onChange={(e) => setDraft({ ...draft, type: e.target.value })}
                  options={WORKOUT_TYPES.map(t => ({ value: t.id, label: t.label }))} />
              </Field>
            </div>

            <Field label="Workout title">
              <Input value={draft.title} placeholder="e.g. Lower Body Strength"
                onChange={(e) => setDraft({ ...draft, title: e.target.value })} />
            </Field>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <Field label="Duration (min)">
                <Input type="number" value={draft.duration}
                  onChange={(e) => setDraft({ ...draft, duration: e.target.value })} />
              </Field>
              <Field label="Intensity">
                <Select value={draft.intensity}
                  onChange={(e) => setDraft({ ...draft, intensity: e.target.value })}
                  options={[
                    { value: "Easy",          label: "Easy" },
                    { value: "Moderate",      label: "Moderate" },
                    { value: "Moderate–Hard", label: "Moderate–Hard" },
                    { value: "Hard",          label: "Hard" },
                    { value: "All-out",       label: "All-out" },
                  ]} />
              </Field>
            </div>

            <Field label="Coach's note (optional)">
              <textarea value={draft.notes}
                onChange={(e) => setDraft({ ...draft, notes: e.target.value })}
                placeholder="Form cues, focus points, scaling options..."
                style={{ ...inputStyle, minHeight: 60, resize: "vertical", fontFamily: FONT_BODY }} />
            </Field>

            {/* Exercises builder */}
            <div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <span style={{ fontFamily: FONT_MONO, fontSize: 9, letterSpacing: 1.5,
                  color: T.muted, textTransform: "uppercase" }}>Exercises</span>
                <button onClick={addEx} type="button"
                  style={{ background: "none", border: "none", color: T.pacific, cursor: "pointer",
                    fontFamily: FONT_MONO, fontSize: 10, letterSpacing: 1, display: "flex", alignItems: "center", gap: 4 }}>
                  <Plus size={11} /> ADD
                </button>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {draft.exercises.map((ex, i) => (
                  <div key={i} style={{
                    display: "grid", gridTemplateColumns: "1.6fr 0.5fr 0.7fr 0.9fr auto",
                    gap: 6, alignItems: "center",
                  }}>
                    <Input placeholder="Exercise" value={ex.name}
                      onChange={(e) => updateEx(i, "name", e.target.value)} />
                    <Input placeholder="Sets" value={ex.sets}
                      onChange={(e) => updateEx(i, "sets", e.target.value)} />
                    <Input placeholder="Reps" value={ex.reps}
                      onChange={(e) => updateEx(i, "reps", e.target.value)} />
                    <Input placeholder="Load" value={ex.load}
                      onChange={(e) => updateEx(i, "load", e.target.value)} />
                    <button onClick={() => removeEx(i)} type="button"
                      style={{ background: "none", border: "none", color: T.danger, cursor: "pointer" }}>
                      <Trash2 size={14} />
                    </button>
                  </div>
                ))}
              </div>
            </div>

            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", marginTop: 8 }}>
              <Btn variant="ghost" onClick={cancel}>Cancel</Btn>
              <Btn icon={Save} onClick={save} disabled={!draft.title.trim() || !draft.date}>
                Save Workout
              </Btn>
            </div>
          </div>
        </Card>
      )}
    </div>
  );
}

