function CalendarManager({ events, setEvents }) {
  const [form, setForm] = useState({ date: todayISO(), title: "", time: "", notes: "", kind: "checkin" });

  const add = () => {
    if (!form.title.trim() || !form.date) return;
    setEvents(prev => [...prev, { id: `e-${Date.now()}`, ...form, title: form.title.trim() }]);
    setForm({ date: todayISO(), title: "", time: "", notes: "", kind: "checkin" });
  };
  const remove = (id) => setEvents(prev => prev.filter(e => e.id !== id));

  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
      <Card>
        <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14, letterSpacing: 2, color: T.pacific, marginBottom: 14 }}>
          NEW EVENT
        </div>
        <div style={{ display: "grid", gap: 10 }}>
          <Field label="Date">
            <Input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
          </Field>
          <Field label="Type">
            <Select value={form.kind}
              onChange={(e) => setForm({ ...form, kind: e.target.value })}
              options={[
                { value: "checkin", label: "Check-in / Call" },
                { value: "rest",    label: "Rest day" },
                { value: "test",    label: "Assessment / Test" },
                { value: "other",   label: "Other" },
              ]} />
          </Field>
          <Field label="Title">
            <Input value={form.title} placeholder="e.g. Weekly check-in"
              onChange={(e) => setForm({ ...form, title: e.target.value })} />
          </Field>
          <Field label="Time (optional)">
            <Input type="time" value={form.time} onChange={(e) => setForm({ ...form, time: e.target.value })} />
          </Field>
          <Field label="Notes">
            <Input value={form.notes} placeholder="Optional"
              onChange={(e) => setForm({ ...form, notes: e.target.value })} />
          </Field>
          <Btn icon={Plus} onClick={add} disabled={!form.title.trim()}>Add Event</Btn>
        </div>
      </Card>

      <Card>
        <div style={{ fontFamily: FONT_DISPLAY, fontSize: 14, letterSpacing: 2, color: T.text, marginBottom: 14 }}>
          UPCOMING ({events.length})
        </div>
        {events.length === 0 ? (
          <div style={{ color: T.muted, fontSize: 13, padding: 16, textAlign: "center" }}>
            No events. Add one to start.
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {[...events].sort((a, b) => a.date.localeCompare(b.date)).map(e => (
              <div key={e.id} style={{
                background: T.surface, border: `1px solid ${T.border}`,
                borderRadius: 8, padding: "10px 12px",
                display: "flex", alignItems: "center", gap: 10,
              }}>
                <div style={{ fontFamily: FONT_MONO, fontSize: 10, color: T.pacific, minWidth: 80 }}>
                  {e.date}
                </div>
                {e.time && <Pill color={T.warn}>{e.time}</Pill>}
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, color: T.text, fontWeight: 600 }}>{e.title}</div>
                  {e.notes && <div style={{ fontSize: 11, color: T.muted }}>{e.notes}</div>}
                </div>
                <button onClick={() => remove(e.id)} type="button"
                  style={{ background: "none", border: "none", color: T.danger, cursor: "pointer" }}>
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

function CoachMessaging({ athlete, messages, setMessages }) {
  const [draft, setDraft] = useState("");
  const send = () => {
    if (!draft.trim()) return;
    setMessages(prev => [...prev, { id: Date.now(), from: "coach", text: draft.trim(), time: "just now" }]);
    setDraft("");
  };

  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16, paddingBottom: 14,
        borderBottom: `1px solid ${T.border}` }}>
        <Avatar initials={athlete.avatar} />
        <div>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, letterSpacing: 1, color: T.text }}>
            {athlete.name.toUpperCase()}
          </div>
          <div style={{ fontFamily: FONT_MONO, fontSize: 10, color: T.muted }}>{athlete.email}</div>
        </div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 8, maxHeight: 420, overflowY: "auto", marginBottom: 12 }}>
        {messages.length === 0 ? (
          <div style={{ color: T.muted, textAlign: "center", padding: 30, fontSize: 13 }}>
            No messages yet. Say hi!
          </div>
        ) : messages.map(m => (
          <div key={m.id} style={{
            alignSelf: m.from === "coach" ? "flex-end" : "flex-start",
            maxWidth: "78%",
            background: m.from === "coach" ? T.pacific : T.surface,
            color: m.from === "coach" ? T.bgDeep : T.text,
            padding: "10px 14px", borderRadius: 12,
            border: m.from === "coach" ? "none" : `1px solid ${T.border}`,
          }}>
            <div style={{ fontSize: 13 }}>{m.text}</div>
            <div style={{ fontFamily: FONT_MONO, fontSize: 9, opacity: 0.7, marginTop: 4 }}>{m.time}</div>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: 8 }}>
        <Input value={draft} onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && send()}
          placeholder={`Message ${athlete.name.split(" ")[0]}...`} />
        <Btn onClick={send} icon={Send} disabled={!draft.trim()}>Send</Btn>
      </div>
    </Card>
  );
}

// ────────────────────────────────────────────────────────────────────
// ROOT — role toggle + state
// ────────────────────────────────────────────────────────────────────
export default function App() {
  const [role, setRole] = useState("athlete"); // 'athlete' | 'coach'
  const [athletes] = useState(seedAthletes());
  const [workoutsByAthlete, setWorkoutsByAthlete] = useState(seedWorkouts());
  const [eventsByAthlete, setEventsByAthlete]     = useState(seedEvents());
  const [messagesByAthlete, setMessagesByAthlete] = useState(seedMessages());
  const [foodLogByAthlete, setFoodLogByAthlete]   = useState(seedFoodLog());
  const [weightLogByAthlete, setWeightLogByAthlete] = useState(seedWeightLog());
  const [moodLogByAthlete, setMoodLogByAthlete]     = useState(seedMoodLog());
  const [stepsLogByAthlete, setStepsLogByAthlete]   = useState(seedStepsLog());
  const [waterLogByAthlete, setWaterLogByAthlete]   = useState(seedWaterLog());
  const [sleepLogByAthlete, setSleepLogByAthlete]   = useState(seedSleepLog());
  const [liftLogByAthlete, setLiftLogByAthlete]     = useState(seedLiftLog());

  // For the athlete demo, always show the first athlete
  const currentAthlete = athletes[0];
  const currentWorkouts = workoutsByAthlete[currentAthlete.id] || {};
  const currentEvents   = eventsByAthlete[currentAthlete.id]   || [];
  const currentMessages = messagesByAthlete[currentAthlete.id] || [];
  const currentFoodLog  = foodLogByAthlete[currentAthlete.id]  || [];
  const currentWeightLog = weightLogByAthlete[currentAthlete.id] || [];
  const currentMoodLog   = moodLogByAthlete[currentAthlete.id]   || [];
  const currentStepsLog  = stepsLogByAthlete[currentAthlete.id]  || [];
  const currentWaterLog  = waterLogByAthlete[currentAthlete.id]  || [];
  const currentSleepLog  = sleepLogByAthlete[currentAthlete.id]  || [];
  const currentLiftLog   = liftLogByAthlete[currentAthlete.id]   || {};

  const sendAthleteMessage = (text) => {
    setMessagesByAthlete(prev => ({
      ...prev,
      [currentAthlete.id]: [
        ...(prev[currentAthlete.id] || []),
        { id: Date.now(), from: "athlete", text, time: "just now" },
      ],
    }));
  };

  const addFood = (entry) => {
    setFoodLogByAthlete(prev => ({
      ...prev,
      [currentAthlete.id]: [...(prev[currentAthlete.id] || []), entry],
    }));
  };

  // Replace-by-date is consistent for all daily measurements
  const replaceByDate = (setter) => (entry) => {
    setter(prev => {
      const existing = (prev[currentAthlete.id] || []).filter(x => x.date !== entry.date);
      return { ...prev, [currentAthlete.id]: [...existing, entry] };
    });
  };

  const addWeight = replaceByDate(setWeightLogByAthlete);
  const addMood   = replaceByDate(setMoodLogByAthlete);
  const addSteps  = replaceByDate(setStepsLogByAthlete);
  const addSleep  = replaceByDate(setSleepLogByAthlete);

  // Water is incremental — adds to today's existing total
  const addWater = (amount) => {
    setWaterLogByAthlete(prev => {
      const list = prev[currentAthlete.id] || [];
      const today = todayISO();
      const existing = list.find(w => w.date === today);
      const others = list.filter(w => w.date !== today);
      const ml = (existing ? existing.ml : 0) + amount;
      return { ...prev, [currentAthlete.id]: [...others, { date: today, ml }] };
    });
  };

  // Lift logging — keyed by exercise name, replaces same-date entry
  const addLift = (exerciseName, entry) => {
    setLiftLogByAthlete(prev => {
      const athleteLifts = prev[currentAthlete.id] || {};
      const exerciseHistory = (athleteLifts[exerciseName] || []).filter(s => s.date !== entry.date);
      return {
        ...prev,
        [currentAthlete.id]: {
          ...athleteLifts,
          [exerciseName]: [...exerciseHistory, entry].sort((a, b) => a.date.localeCompare(b.date)),
        },
      };
    });
  };

  return (
    <>
      <DemoBanner role={role} setRole={setRole} />
      {role === "athlete" ? (
        <AthleteApp
          athlete={currentAthlete}
          workouts={currentWorkouts}
          events={currentEvents}
          messages={currentMessages}
          foodLog={currentFoodLog}
          weightLog={currentWeightLog}
          moodLog={currentMoodLog}
          stepsLog={currentStepsLog}
          waterLog={currentWaterLog}
          sleepLog={currentSleepLog}
          liftLog={currentLiftLog}
          onAddFood={addFood}
          onAddWeight={addWeight}
          onAddMood={addMood}
          onAddSteps={addSteps}
          onAddWater={addWater}
          onAddSleep={addSleep}
          onLogLift={addLift}
          onSendMessage={sendAthleteMessage}
        />
      ) : (
        <CoachApp
          athletes={athletes}
          workoutsByAthlete={workoutsByAthlete}
          eventsByAthlete={eventsByAthlete}
          messagesByAthlete={messagesByAthlete}
          weightLogByAthlete={weightLogByAthlete}
          moodLogByAthlete={moodLogByAthlete}
          stepsLogByAthlete={stepsLogByAthlete}
          waterLogByAthlete={waterLogByAthlete}
          sleepLogByAthlete={sleepLogByAthlete}
          liftLogByAthlete={liftLogByAthlete}
          setWorkoutsByAthlete={setWorkoutsByAthlete}
          setEventsByAthlete={setEventsByAthlete}
          setMessagesByAthlete={setMessagesByAthlete}
        />
      )}
    </>
  );
}

function DemoBanner({ role, setRole }) {
  const [open, setOpen] = useState(true);
  return (
    <div style={{
      position: "fixed", top: 12, right: 12, zIndex: 100,
      background: T.bgDeep, border: `1px solid ${T.border}`, borderRadius: 12,
      padding: open ? "12px 14px" : "10px 12px",
      maxWidth: 320, boxShadow: "0 8px 32px rgba(28, 25, 21, 0.12)",
    }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <div style={{ width: 8, height: 8, borderRadius: "50%", background: T.pacific,
            boxShadow: `0 0 8px ${T.pacific}` }} />
          <span style={{ fontFamily: FONT_DISPLAY, fontSize: 12, letterSpacing: 1.5, color: T.pacific }}>
            DEMO PROTOTYPE
          </span>
        </div>
        <button onClick={() => setOpen(!open)} type="button"
          style={{ background: "none", border: "none", color: T.muted, cursor: "pointer", padding: 0 }}>
          {open ? <X size={14} /> : <ChevronLeft size={14} />}
        </button>
      </div>

      {open && (
        <>
          <div style={{ color: T.muted, fontSize: 11, lineHeight: 1.5, marginTop: 8 }}>
            UI preview only. Mock data resets on reload. Backend not connected.
          </div>
          <div style={{ marginTop: 10, display: "flex", gap: 6, padding: 3,
            background: T.surface, borderRadius: 8, border: `1px solid ${T.border}` }}>
            <button onClick={() => setRole("athlete")} type="button"
              style={{
                flex: 1, padding: "8px 12px", borderRadius: 6, border: "none", cursor: "pointer",
                background: role === "athlete" ? T.pacific : "transparent",
                color: role === "athlete" ? T.bgDeep : T.muted,
                fontFamily: FONT_DISPLAY, fontSize: 11, letterSpacing: 1.5,
              }}>CLIENT</button>
            <button onClick={() => setRole("coach")} type="button"
              style={{
                flex: 1, padding: "8px 12px", borderRadius: 6, border: "none", cursor: "pointer",
                background: role === "coach" ? T.pacific : "transparent",
                color: role === "coach" ? T.bgDeep : T.muted,
                fontFamily: FONT_DISPLAY, fontSize: 11, letterSpacing: 1.5,
              }}>COACH</button>
          </div>
        </>
      )}
    </div>
  );
}
